import csv
import io
import json


def team_report(text):
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames is None or 'team' not in reader.fieldnames or 'score' not in reader.fieldnames:
        raise ValueError('the header must name a team and a score column')
    totals = {}
    for row in reader:
        if row['team'] is None or row['score'] is None:
            raise ValueError(f'row {reader.line_num} is incomplete')
        count, total = totals.get(row['team'], (0, 0))
        totals[row['team']] = (count + 1, total + int(row['score']))
    report = {team: {'count': c, 'mean': t / c} for team, (c, t) in totals.items()}
    return json.dumps(report, sort_keys=True)


def best_team(report_json):
    report = json.loads(report_json)
    if not isinstance(report, dict) or not report:
        raise ValueError('expected a non-empty JSON object')
    top = max(v['mean'] for v in report.values())
    return min(team for team, v in report.items() if v['mean'] == top)

